@startuml

class City {}

class H2SLocation {
  +LocationID : string
}

class Resident {
  +Name : string
  +StreetAddress : string
  +PhoneNumber : string
  +Email : string
}

class PickupRequest {
  +RequestID : string
  +ItemDescription : string
  +RequestedDate : date
  +RequestedTime : time
}

class Vehicle {
  +LicensePlate : string
  +StorageCapacity : float
}

class PickupRoute {
  +RouteID : string
  +Date : date
}

class VolunteerDriver {
  +DriverID : string
  +Name : string
}

class DistributionCenter {
  +CenterID : string
}

class Article {
  +RFIDTag : string
  +Description : string
  +Weight : float
  +Dimensions : string
}

enum ArticleCategory {
  BabyClothing
  WomensWinterBoots
  Fridge
  Microwave
}

class FoodItem {
  +Description : string
}

class Client {
  +Name : string
  +HomeAddress : string
}

class DeliveryRequest {
  +DeliveryDate : date
}

City "1" -- "0..*" H2SLocation
H2SLocation "1" -- "1" DistributionCenter
Resident "1" -- "0..*" PickupRequest
PickupRequest "1" -- "1" Vehicle
PickupRequest "1" -- "1" VolunteerDriver
Vehicle "1" -- "0..*" PickupRoute
VolunteerDriver "1" -- "0..*" PickupRoute
PickupRoute "1" -- "1..*" PickupRequest
DistributionCenter "1" -- "0..*" Article
Article "1" -- "1" ArticleCategory
Resident "1" -- "0..*" FoodItem
DistributionCenter "1" -- "0..*" FoodItem
Client "1" -- "0..*" DeliveryRequest
DeliveryRequest "1" -- "1" Article
VolunteerDriver "1" -- "0..*" DeliveryRequest

@enduml

